cudaStream_t stream;CK(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));cudaGraph_t graphs[4];cudaGraphExec_t exec[4];for(int route=0;route<4;route++){CK(cudaStreamBeginCapture(stream,cudaStreamCaptureModeThreadLocal));for(int j=0;j<100;j++){if(route==0){LAUNCH(false,stream);}else if(route==1){LAUNCH(true,stream);}else if(route==2)direct<<<db,256,0,stream>>>(input,ref);else lookup<<<db,256,0,stream>>>(input,out,table);}CK(cudaStreamEndCapture(stream,&graphs[route]));CK(cudaGraphInstantiate(&exec[route],graphs[route],0));for(int j=0;j<5;j++)CK(cudaGraphLaunch(exec[route],stream));}CK(cudaStreamSynchronize(stream));cudaEvent_t start,end;CK(cudaEventCreate(&start));CK(cudaEventCreate(&end));std::vector<float>times[4];for(int round=0;round<7;round++)for(int j=0;j<4;j++){int route=(round+j)%4;CK(cudaEventRecord(start,stream));CK(cudaGraphLaunch(exec[route],stream));CK(cudaEventRecord(end,stream));CK(cudaEventSynchronize(end));float ms;CK(cudaEventElapsedTime(&ms,start,end));times[route].push_back(ms/100);}cudaFuncAttributes attrs[4];CK(cudaFuncGetAttributes(attrs+0,native<false,0,false>));CK(cudaFuncGetAttributes(attrs+1,native<true,0,false>));CK(cudaFuncGetAttributes(attrs+2,direct));CK(cudaFuncGetAttributes(attrs+3,lookup));printf("{\"status\":\"pass\",\"cases\":54675,\"validation_checks\":%d,\"missing\":%llu,\"mismatches\":%llu,\"producer_bytes\":2448,\"native_dense_bytes\":90504,\"source_lookup_bytes\":218700,\"input_bytes\":218700,\"output_bytes\":218700,\"timings_ms\":{",N*32*4*2,counters[0],counters[1]);const char*names[]={"two_MMA_affine","one_MMA_C_fused","direct_Q8","full_map_lookup"};for(int j=0;j<4;j++){std::sort(times[j].begin(),times[j].end());printf("%s\"%s\":{\"median\":%.6f,\"min\":%.6f,\"max\":%.6f,\"registers\":%d,\"local_bytes\":%zu,\"shared_bytes\":%zu}",j?",":"",names[j],times[j][3],times[j][0],times[j][6],attrs[j].numRegs,attrs[j].localSizeBytes,attrs[j].sharedSizeBytes);}printf("},\"scope\":\"2448B producer; exact float-bit checked dense 